#!/usr/bin/python3
"""Validate and atomically unpack a supplier tar archive into incoming/."""
from __future__ import print_function

import os
import posixpath
import shutil
import stat
import sys
import tarfile
import tempfile


def fail(message):
    print("unpack: " + message, file=sys.stderr)
    raise SystemExit(2)


def member_path(name):
    if not name or name.startswith("/"):
        fail("unsafe absolute or empty member path: {!r}".format(name))
    parts = name.split("/")
    if ".." in parts:
        fail("unsafe parent traversal in member path: {!r}".format(name))
    clean = posixpath.normpath(name)
    if clean in ("", ".") or clean.startswith("../"):
        fail("unsafe member path: {!r}".format(name))
    return clean


def validate(members):
    seen = set()
    kinds = {}
    checked = []
    for member in members:
        name = member_path(member.name)
        if name in seen:
            fail("duplicate archive member: {!r}".format(member.name))
        seen.add(name)
        if member.issym() or member.islnk():
            fail("links are not permitted: {!r}".format(member.name))
        if not (member.isdir() or member.isreg()):
            fail("unsupported archive member type: {!r}".format(member.name))
        kinds[name] = "dir" if member.isdir() else "file"
        checked.append((member, name))

    for name in kinds:
        parent = posixpath.dirname(name)
        while parent and parent != ".":
            if kinds.get(parent) == "file":
                fail("member has a non-directory parent: {!r}".format(name))
            parent = posixpath.dirname(parent)
    return checked


def check_existing(root):
    info = os.lstat(root)
    if not stat.S_ISDIR(info.st_mode):
        fail("incoming exists but is not a real directory")
    for current, dirs, files in os.walk(root, topdown=True, followlinks=False):
        for entry in dirs + files:
            path = os.path.join(current, entry)
            mode = os.lstat(path).st_mode
            if not (stat.S_ISDIR(mode) or stat.S_ISREG(mode)):
                fail("incoming contains a link or special file: {!r}".format(path))


def safe_mode(mode, is_dir):
    return mode & (0o777 if is_dir else 0o666)


def main():
    if len(sys.argv) != 2:
        fail("usage: unpack ARCHIVE")

    base = os.path.dirname(os.path.dirname(os.path.realpath(__file__)))
    incoming = os.path.join(base, "incoming")
    archive = os.path.abspath(sys.argv[1])

    try:
        tf = tarfile.open(archive, mode="r:*")
    except (OSError, tarfile.TarError) as exc:
        fail("cannot read archive: {}".format(exc))

    stage = None
    backup = None
    try:
        checked = validate(tf.getmembers())

        if os.path.lexists(incoming):
            check_existing(incoming)
            stage = tempfile.mkdtemp(prefix=".incoming-stage-", dir=base)
            os.rmdir(stage)
            shutil.copytree(incoming, stage, symlinks=True)
        else:
            stage = tempfile.mkdtemp(prefix=".incoming-stage-", dir=base)

        for member, name in checked:
            target = os.path.join(stage, *name.split("/"))
            if member.isdir():
                if os.path.exists(target) and not os.path.isdir(target):
                    fail("directory conflicts with an existing file: {!r}".format(name))
                if not os.path.isdir(target):
                    os.makedirs(target)
                os.chmod(target, safe_mode(member.mode, True))
                continue

            parent = os.path.dirname(target)
            if not os.path.isdir(parent):
                os.makedirs(parent)
            if os.path.isdir(target):
                fail("file conflicts with an existing directory: {!r}".format(name))
            source = tf.extractfile(member)
            if source is None:
                fail("cannot read archive member: {!r}".format(name))
            with source:
                with open(target, "wb") as output:
                    shutil.copyfileobj(source, output, 1024 * 1024)
            os.chmod(target, safe_mode(member.mode, False))

        backup = tempfile.mkdtemp(prefix=".incoming-old-", dir=base)
        os.rmdir(backup)
        if os.path.lexists(incoming):
            os.rename(incoming, backup)
        else:
            backup = None
        try:
            os.rename(stage, incoming)
            stage = None
        except Exception:
            if backup is not None:
                os.rename(backup, incoming)
                backup = None
            raise
        if backup is not None:
            shutil.rmtree(backup)
            backup = None
    except SystemExit:
        raise
    except (OSError, tarfile.TarError) as exc:
        fail("archive was not installed: {}".format(exc))
    finally:
        tf.close()
        if stage is not None and os.path.isdir(stage):
            shutil.rmtree(stage)
        if backup is not None and os.path.isdir(backup):
            shutil.rmtree(backup)


if __name__ == "__main__":
    main()
